//! Cross-checks every verified setup's rule conditions against SRS
//! reachability. `tests/fixtures/ijlo_reachable_orders.json` is generated by
//! `python -I tools/ijlo_solves.py fixtures` and lists, per setup, the
//! following-bag orders whose solve can actually be played; the conditions in
//! data/ijlo.json must accept exactly those orders once the bag is disclosed.
//! save O additionally waits for both queue setups to fail, as the source
//! uses it only when they cannot be built.

use std::{collections::BTreeMap, path::PathBuf};

use pc_overlay_core::{EvalContext, Piece, RuleSet, condition::EvalResult, rules::ReviewStatus};
use serde::Deserialize;

#[derive(Deserialize)]
struct ReachableOrders {
    orders: BTreeMap<String, Vec<String>>,
}

const BAG: [Piece; 7] = [
    Piece::T,
    Piece::I,
    Piece::J,
    Piece::L,
    Piece::O,
    Piece::S,
    Piece::Z,
];

fn code(piece: Piece) -> char {
    match piece {
        Piece::I => 'I',
        Piece::J => 'J',
        Piece::L => 'L',
        Piece::O => 'O',
        Piece::S => 'S',
        Piece::T => 'T',
        Piece::Z => 'Z',
    }
}

fn permutations(items: &mut Vec<Piece>, start: usize, out: &mut Vec<Vec<Piece>>) {
    if start == items.len() {
        out.push(items.clone());
        return;
    }
    for index in start..items.len() {
        items.swap(start, index);
        permutations(items, start + 1, out);
        items.swap(start, index);
    }
}

fn closed(order: &[Piece]) -> EvalContext {
    EvalContext {
        queue_history: order.to_vec(),
        queue_closed: true,
        hold: None,
        current: order[0],
        accessible: Default::default(),
        case_hold: None,
        case_queue: Vec::new(),
    }
}

#[test]
fn verified_conditions_accept_exactly_the_reachable_orders() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let rules = RuleSet::load(root.join("data/ijlo.json")).unwrap();
    let table: ReachableOrders = serde_json::from_str(
        &std::fs::read_to_string(root.join("tests/fixtures/ijlo_reachable_orders.json")).unwrap(),
    )
    .unwrap();
    let mut orders = Vec::new();
    permutations(&mut BAG.to_vec(), 0, &mut orders);
    assert_eq!(orders.len(), 5040);

    let queue_fails = |order: &Vec<Piece>| {
        ["ijlo_s_queue", "ijlo_z_queue"].iter().all(|id| {
            let setup = rules.setup("ijlo_source_method", id).unwrap();
            let fail = setup.fail_condition.as_ref().unwrap();
            fail.evaluate(&closed(order)) == EvalResult::Satisfied
        })
    };
    let mut checked = Vec::new();
    for setup in rules.methods.iter().flat_map(|method| &method.setups) {
        if setup.review_status != ReviewStatus::Verified {
            continue;
        }
        let reachable = &table.orders[&setup.id];
        for order in &orders {
            let context = closed(order);
            // The S/Z build conditions (`seen S` / `seen Z`) only rank the two
            // setups; whether they can be solved is their fail condition.
            let accepted = match &setup.fail_condition {
                Some(fail) => fail.evaluate(&context) == EvalResult::Failed,
                None => setup.build_condition.evaluate(&context) == EvalResult::Satisfied,
            };
            let text: String = order.iter().copied().map(code).collect();
            let expected =
                reachable.contains(&text) && (setup.fail_condition.is_some() || queue_fails(order));
            assert_eq!(accepted, expected, "{}: {text}", setup.id);
        }
        checked.push(setup.id.clone());
    }
    assert_eq!(
        checked,
        [
            "ijlo_s_queue",
            "ijlo_z_queue",
            "ijlo_save_o_left",
            "ijlo_save_o_right"
        ]
    );
}

#[test]
fn save_o_side_is_decided_while_the_bag_is_still_partly_hidden() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let rules = RuleSet::load(root.join("data/ijlo.json")).unwrap();
    let left = rules
        .setup("ijlo_source_method", "ijlo_save_o_left")
        .unwrap();
    let context = |pieces: &[Piece]| EvalContext {
        queue_history: pieces.to_vec(),
        queue_closed: false,
        hold: None,
        current: Piece::T,
        accessible: Default::default(),
        case_hold: None,
        case_queue: Vec::new(),
    };
    use Piece::{I, J, L, O, S, T, Z};
    // T J L: every remaining order can be played, and S and Z come after
    // T J and T L, so both queue setups have already failed.
    assert_eq!(
        left.build_condition.evaluate(&context(&[T, J, L])),
        EvalResult::Satisfied
    );
    // T J alone: playable either way, but Z might still beat L.
    assert_eq!(
        left.build_condition.evaluate(&context(&[T, J])),
        EvalResult::Pending
    );
    // O first fills HOLD, and I then precedes J.
    assert_eq!(
        left.build_condition
            .evaluate(&context(&[O, I, L, T, J, S, Z])),
        EvalResult::Failed
    );
}
